parameters.content:
## 입력 계약

```json
{
  "apiBaseUrl": "https://backend.example",
  "options": {
    "targetEligibility": "REVIEW"
  }
}
```

운영에서는 `$env.PAI_LOOP_API_BASE_URL`이 입력값보다 우선합니다. Webhook이 직접 공급하는 URL은 HTTPS만 허용하고, URL 내 계정정보는 거부합니다.

parameters.jsCode:
return [{
  json: {
    triggerSource: 'manual',
    apiBaseUrl: '',
    options: { targetEligibility: 'REVIEW' }
  }
}];

const source = $json ?? {};
const body = source.body && typeof source.body === 'object' ? source.body : source;
let envBaseUrl = '';
try {
  envBaseUrl = String($env.PAI_LOOP_API_BASE_URL ?? '').trim();
} catch {
  envBaseUrl = '';
}
const inputBaseUrl = String(body.apiBaseUrl ?? body.api_base_url ?? '').trim();
const selectedBaseUrl = envBaseUrl || inputBaseUrl;
let apiBaseUrl = '';
if (selectedBaseUrl) {
  let parsed;
  try {
    parsed = new URL(selectedBaseUrl);
  } catch {
    throw new Error('apiBaseUrl must be an absolute HTTP(S) URL');
  }
  if (!['http:', 'https:'].includes(parsed.protocol) || parsed.username || parsed.password) {
    throw new Error('apiBaseUrl must use HTTP(S) without embedded credentials');
  }
  if (!envBaseUrl && source.headers && parsed.protocol !== 'https:') {
    throw new Error('Webhook-supplied apiBaseUrl must use HTTPS');
  }
  apiBaseUrl = parsed.toString().replace(/\/+$/, '');
}
const targetEligibility = String(body.options?.targetEligibility ?? 'REVIEW').toUpperCase();
if (targetEligibility !== 'REVIEW') {
  throw new Error('This vertical slice intentionally selects targetEligibility=REVIEW');
}
return [{
  json: {
    triggerSource: source.headers ? 'webhook' : (body.triggerSource ?? 'manual'),
    runtime: {
      apiBaseUrl,
      dryRun: apiBaseUrl.length === 0,
      apiBaseUrlSource: envBaseUrl ? 'environment' : (inputBaseUrl ? 'workflow-input' : 'none')
    },
    request: { targetEligibility }
  }
}];

const response = $json ?? {};
const replay = response.body && typeof response.body === 'object' ? response.body : response;
if (typeof replay.fixture_version !== 'string' || !replay.fixture_version) {
  throw new Error('Replay response.fixture_version is required');
}
if (!Number.isInteger(replay.created) || !Number.isInteger(replay.existing)) {
  throw new Error('Replay response.created and existing must be integers');
}
if (!Array.isArray(replay.notice_keys) || replay.notice_keys.length === 0) {
  throw new Error('Replay response.notice_keys must be a non-empty array');
}
const apiBaseUrl = response.runtime?.apiBaseUrl;
if (!apiBaseUrl) {
  throw new Error('Merged replay runtime is missing apiBaseUrl');
}
const summary = {
  fixtureVersion: replay.fixture_version,
  created: replay.created,
  existing: replay.existing,
  noticeKeys: replay.notice_keys.map(String),
  note: String(replay.note ?? '')
};
return summary.noticeKeys.map((noticeKey) => ({
  json: {
    apiBaseUrl,
    targetEligibility: response.request?.targetEligibility ?? 'REVIEW',
    noticeKey,
    replay: summary
  },
  pairedItem: { item: 0 }
}));

const items = $input.all();
const reviews = items.filter((item) => item.json?.latest_evaluation?.eligibility === 'REVIEW');
if (reviews.length !== 1) {
  throw new Error(`Expected exactly one REVIEW notice detail, received ${reviews.length}`);
}
return reviews;

const detail = $json ?? {};
const evaluation = detail.latest_evaluation;
if (!evaluation || typeof evaluation !== 'object') {
  throw new Error('Notice detail.latest_evaluation is required');
}
const requireEnum = (field, value, allowed) => {
  if (!allowed.includes(value)) {
    throw new Error(`${field} must be one of: ${allowed.join(', ')}`);
  }
  return value;
};
const eligibility = requireEnum('eligibility', evaluation.eligibility, ['PASS', 'REVIEW', 'FAIL']);
const reasonCode = String(evaluation.reason_code ?? '');
if (!reasonCode) {
  throw new Error('latest_evaluation.reason_code is required');
}
if (reasonCode === 'DF-000' && eligibility !== 'FAIL') {
  throw new Error('reason_code=DF-000 is only valid with eligibility=FAIL');
}
const readinessStatus = requireEnum(
  'readiness_status',
  evaluation.readiness_status,
  ['GREEN', 'YELLOW', 'RED', 'GRAY']
);
const riskBand = requireEnum(
  'risk_band',
  evaluation.risk_band,
  ['GO', 'CONDITIONAL_GO', 'NO_GO', 'UNKNOWN']
);
const versions = Array.isArray(detail.versions) ? [...detail.versions] : [];
versions.sort((a, b) => Number(b.version_no ?? 0) - Number(a.version_no ?? 0));
const latestVersion = versions[0] ?? null;
const documentStatus = latestVersion?.document_complete === true && latestVersion?.extraction_status === 'COMPLETE'
  ? 'COMPLETE'
  : 'INCOMPLETE';
const atomicResults = Array.isArray(evaluation.atomic_results) ? evaluation.atomic_results : [];
return [{
  json: {
    schemaVersion: '1.0',
    executionMode: String(detail._execution_mode ?? 'backend'),
    replay: detail.replay ?? null,
    notice: {
      noticeKey: String(detail.notice_key ?? ''),
      bidNoticeNo: String(detail.bid_notice_no ?? ''),
      revisionNo: String(detail.revision_no ?? ''),
      title: String(detail.title ?? ''),
      agency: String(detail.agency ?? ''),
      deadline: detail.deadline ?? null,
      status: String(detail.status ?? ''),
      estimatedAmount: detail.estimated_amount ?? null,
      sourceUrl: detail.source_url ?? null,
      latestVersion
    },
    assessment: {
      documentStatus,
      eligibility,
      reasonCode,
      defaultFail: eligibility === 'FAIL' && reasonCode === 'DF-000',
      readinessScore: Number(evaluation.readiness_score),
      readinessStatus,
      evidenceCoverage: Number(evaluation.evidence_coverage),
      riskScore: evaluation.risk_score == null ? null : Number(evaluation.risk_score),
      riskBand,
      rulesetVersion: String(evaluation.ruleset_version ?? ''),
      atomicResults,
      explanation: evaluation.explanation ?? {}
    },
    completedAt: new Date().toISOString()
  }
}];
